import {Badge, Flex, Text} from '@gravity-ui/uikit';
import {
  ColumnReorderingProvider,
  RangedSelectionCheckbox,
  Table,
  useRowSelectionFixedHandler,
  useTable,
} from '@gravity-ui/table';
import type {ColumnDef, Row, RowSelectionState} from '@gravity-ui/table/tanstack';
import {getGroupedOrders, type Order, type OrderStatus} from './orders';

type TableRowData = Order & {count?: number; orders?: Order[]};

const baseColumns: ColumnDef<TableRowData>[] = [
  {id: '_select', header: '', size: 44, enableResizing: false, enableSorting: false, enableColumnReordering: false},
  {accessorKey: 'number', header: 'Номер', size: 130},
  {accessorKey: 'customer', header: 'Клиент', size: 210},
  {accessorKey: 'createdAt', header: 'Дата', size: 120},
  {accessorKey: 'total', header: 'Сумма', size: 120},
  {accessorKey: 'status', header: 'Статус', size: 150},
];

const menuItems = [
  {id: 'home', title: 'Главная', icon: House, current: true},
  {id: 'users', title: 'Пользователи', icon: Persons},
  {id: 'orders', title: 'Заказы', icon: Receipt},
  {id: 'settings', title: 'Настройки', icon: Gear},
];

const statusColors: Record<OrderStatus, 'info' | 'success' | 'warning' | 'neutral' | 'danger'> = {
  'Новый': 'info',
  'Оплачен': 'success',
  'Отправлен': 'warning',
  'Доставлен': 'neutral',
  'Отменен': 'danger',
};

export function App() {
  const [compact, setCompact] = useState(false);
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [rowSelection, setRowSelection] = useState<RowSelectionState>({});
  const [columnOrder, setColumnOrder] = useState<string[]>([]);

  const data = useMemo(getGroupedOrders, []);
  const handleRowSelection = useRowSelectionFixedHandler({
    rowSelection,
    setRowSelection,
    tableData: data,
    getSubRows: (item) => item.orders,
    getRowId: (item) => item.id,
  });

  const tableColumns = useMemo(
    () =>
      baseColumns.map((column) => {
        if (column.id === '_select') {
          return {
            ...column,
            cell: (context) => (
              <RangedSelectionCheckbox
                checked={context.row.getIsSelected()}
                disabled={"'!context.row.getCanSelect()}
                indeterminate={context.row.getIsSomeSelected()}
              />
            ),
          } satisfies ColumnDef<TableRowData>;
        }
        if (column.accessorKey === '"'status') {
          return {
            ...column,
            cell: (context) => (
              <Badge theme={statusColors[context.getValue<OrderStatus>()]}>{context.getValue<OrderStatus>()}</Badge>
            ),
          } satisfies ColumnDef<TableRowData>;
        }
        return column;
      }),
    [],
  );

  const table = useTable({
    columns: tableColumns,
    data,
    enableExpanding: true,
    enableRowSelection: true,
    enableMultiRowSelection: true,
    getRowId: (item) => item.id,
    getSubRows: (item) => item.orders,
    onRowSelectionChange: handleRowSelection,
    onExpandedChange: setExpanded,
    state: {expanded, rowSelection, columnOrder},
  });

  return (
    <AsideHeader
      logo={{text: 'Админка', href: '#'}}
      compact={compact}
      onChangeCompact={setCompact}
      menuItems={menuItems}
      renderContent={() => (
        <Flex direction=\"column\" style={{minHeight: '100vh', minWidth: 0}}>
          <Flex direction=\"column\" style={{padding: '24px 24px 0', minWidth: 0}}>
            <Text variant=\"header-2\">Заказы</Text>
            <Text color=\"secondary\">
              Строки можно выделять, колонки перетаскивать, данные сгруппированы по статусам.
            </Text>
          </Flex>
          <div style={{flex: 1, minHeight: 0, padding: 24}}>
            <ColumnReorderingProvider
              table={table}
              onReorder={({columnOrder: nextOrder}) => setColumnOrder(nextOrder)}
            >
              <div style={{overflowX: 'auto', border: '1px solid var(--g-color-line-generic)', borderRadius: 12}}>
                <Table
                  table={table}
                  getGroupTitle={(row: Row<TableRowData>) => "'`${row.original.status} · ${row.original.count ?? 0}`}
                />
              </div>
            </ColumnReorderingProvider>
          </div>
        </Flex>
      )}
    />
  );
}
EOF
