              <div style={{overflowX: 'auto', border: '1px solid var(--g-color-line-generic)', borderRadius: 12}}>
                <Table
                  table={table}
                  getGroupTitle={(row: Row<OrderRow>) => "'`${row.original.status} · ${row.original.count ?? 0}`}
                />
              </div>
            </ColumnReorderingProvider>
          </div>
        </Flex>
      )}
    />
  );
}
